import type {ImageSource} from './image'
import type {PlatformId} from './platform'

export type RunnerCreateForm = {
  name: string
  platform: PlatformId | null
  runnerGroupId: number
  maximumConcurrentJobs: number
  imageId: string | number | null
  imageSource: ImageSource
  imageVersion: string | null
  imageName: string | null
  machineSpecId: string | null
  isPublicIpEnabled: boolean
  imageSasUri: string
  isImageGenerationEnabled: boolean
}

export type RunnerEditForm = {
  imageVersion: string | null
  imageId: string | number | null
  imageSource: ImageSource | null
  isPublicIpEnabled: boolean
  maximumConcurrentJobs: number
  name: string
  runnerGroupId: number
  machineSpecId: string | null
  isImageGenerationEnabled: boolean | null
}

export type RunnerGroup = {
  id: number
  name: string
  visibility: RunnerGroupVisibility
  allowPublic: boolean
  selectedTargets: unknown[]
  precreated: boolean
}

export const RunnerGroupVisibility = {
  All: 'ALL',
  Selected: 'SELECTED',
  Private: 'PRIVATE',
} as const

export type RunnerGroupVisibility = (typeof RunnerGroupVisibility)[keyof typeof RunnerGroupVisibility]
