import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {DocsContext} from '../views/components/context'
import {Button, Flash, Heading, Link, PageLayout} from '@primer/react'
import {Box} from '@primer/styled-react'
import {RunnerNameInput} from '../views/components/shared/RunnerNameInput'
import {useEffect, useState} from 'react'
import {useNavigate} from '@github-ui/use-navigate'
import {
  RunnerMaxConcurrencyInput,
  getMaxRunnerConcurrencyError,
} from '../views/components/shared/RunnerMaxConcurrencyInput'
import {RunnerGroupSelector} from '../views/components/shared/RunnerGroupSelector'
import {RunnerPublicIpCheckbox} from '../views/components/shared/RunnerPublicIpCheckbox'
import type {RunnerEditForm, RunnerGroup} from '../types/runner'
import {ERRORS} from '../helpers/constants'
import {type ImageVersion, type Image, type ImageKey, ImageSource} from '../types/image'
import type {MachineSpec} from '../types/machine-spec'
import {findPlatformById} from '../types/platform'
import {updateRunner} from '../services/runner'
import {runnerDetailsPath} from '../helpers/paths'
import FieldProgression from '../views/components/shared/FieldProgression'
import MachineSpecSelect, {machineSpecDisplayText} from '../views/components/shared/MachineSpecSelect'
import ImageSelector, {findImageByKey} from '../views/components/shared/ImageSelector'
import {ImageVersionSelector} from '../views/components/shared/ImageVersionSelector'
import {getImageDisplayName} from './NewRunner'
import {InlineMessage} from '@primer/react/experimental'

export interface EditRunnerPayload {
  docsUrlBase: string
  entityLogin: string
  imageVersions: ImageVersion[]
  isEnterprise: boolean
  isPublicIpAllowed: boolean
  isRunnerImageEditEnabled: boolean
  maxConcurrentJobsMax: number
  maxConcurrentJobsMin: number
  runnerGroupId: number
  runnerGroups: RunnerGroup[]
  runnerHasCustomImage: boolean
  runnerHasGpuSpec: boolean
  runnerHasPublicIp: boolean
  runnerId: number
  runnerListPath: string
  runnerMaxConcurrentJobs: number
  runnerName: string
  publicIpInfoPath: string
  runnerPlatformId: string
  images: {[key: string]: Image[]}
  runnerImage: ImageKey
  machineSpecs: MachineSpec[]
  runnerMachineSpecId: string
  runnerImageGenerationEnabled: boolean
  isCustomImagesPolicyEnabled: boolean
  isImageGenerationToggleEnabled: boolean
  hidePartnerAndCustomTabs: boolean
}

export function EditRunner() {
  const {
    docsUrlBase,
    entityLogin,
    imageVersions,
    isEnterprise,
    isPublicIpAllowed,
    isRunnerImageEditEnabled,
    maxConcurrentJobsMin,
    maxConcurrentJobsMax,
    runnerGroupId,
    runnerGroups,
    runnerHasCustomImage,
    runnerHasGpuSpec,
    runnerHasPublicIp,
    runnerId,
    runnerListPath,
    runnerMaxConcurrentJobs,
    runnerName,
    publicIpInfoPath,
    runnerPlatformId,
    images,
    runnerImage,
    machineSpecs,
    runnerMachineSpecId,
    runnerImageGenerationEnabled,
    isCustomImagesPolicyEnabled,
    isImageGenerationToggleEnabled,
    hidePartnerAndCustomTabs,
  } = useRoutePayload<EditRunnerPayload>()

  const [formError, setFormError] = useState<string>('')

  const [selectedRunnerName, setSelectedRunnerName] = useState<string>(runnerName)
  const [runnerNameError, setRunnerNameError] = useState<boolean>(false)

  const [maxConcurrentJobs, setMaxConcurrentJobs] = useState<number>(runnerMaxConcurrentJobs)

  const [isPublicIpEnabled, setIsPublicIpEnabled] = useState<boolean>(runnerHasPublicIp)

  // it's not possible to have group with ID 0, so we use it to validate if no groups are available
  const [selectedRunnerGroupId, setSelectedRunnerGroupId] = useState<number>(runnerGroupId)
  const [runnerGroupError, setRunnerGroupError] = useState<boolean>(false)
  const selectedRunnerGroup = runnerGroups.find(g => g.id === selectedRunnerGroupId)

  // State for image generation checkbox - initialized from the pool's current value
  const [isImageGenerationEnabled, setIsImageGenerationEnabled] = useState<boolean>(runnerImageGenerationEnabled)

  // initialize with selected image version based on runnerImageVersion
  const [selectedImageVersion, setSelectedImageVersion] = useState<ImageVersion | null>(
    imageVersions?.find(version => version.version === runnerImage.version) || null,
  )

  const runnerPlatform = findPlatformById(runnerPlatformId)

  const [selectedImage, setSelectedImage] = useState<Image | null>(() => findImageByKey(runnerImage, images))
  const selectedImageDisplayName = getImageDisplayName(selectedImage, selectedImageVersion, isImageGenerationEnabled)
  const [selectedMachineSpec, setSelectedMachineSpec] = useState<MachineSpec | null>(
    machineSpecs.find(spec => spec.id === runnerMachineSpecId) || null,
  )
  const [machineSpecError, setMachineSpecError] = useState<boolean>(false)
  const [imageError, setImageError] = useState<boolean>(false)

  // Curated images are always editable; the FF expands editability to partner/marketplace images
  const canEditImage = isRunnerImageEditEnabled || selectedImage?.source === ImageSource.Curated

  const [fieldProgressionKey, setFieldProgressionKey] = useState(0)

  useEffect(() => {
    // Update the key to force rendering of the FieldProgression component
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setFieldProgressionKey(prevKey => prevKey + 1)
  }, [selectedImageVersion])

  // Tracks the progression of the fields
  const [currentFieldIndex, setCurrentFieldIndex] = useState(-1)

  const navigate = useNavigate()

  const resetFormError = () => {
    setFormError('')
  }

  const isFormValid = () => {
    let validForm = true
    if (!selectedRunnerName || runnerNameError) {
      setRunnerNameError(true)
      validForm = false
    }

    const isGroupInvalid = !runnerGroups.find(group => group.id === runnerGroupId)
    if (!runnerGroupId || isGroupInvalid || runnerGroupError) {
      setRunnerGroupError(true)
      validForm = false
    }

    if (canEditImage && !selectedImage) {
      setImageError(true)
      validForm = false
    }

    if (!selectedMachineSpec) {
      setMachineSpecError(true)
      validForm = false
    }

    const maxRunnerConcurrencyError = getMaxRunnerConcurrencyError({
      value: maxConcurrentJobs,
      min: maxConcurrentJobsMin,
      max: maxConcurrentJobsMax,
      gpuRunnerSelected: runnerHasGpuSpec,
    })
    if (maxRunnerConcurrencyError) {
      validForm = false
    }

    return validForm
  }

  const handleSubmit = async (e: React.FormEvent<EventTarget>) => {
    e.preventDefault()
    resetFormError()

    if (!isFormValid()) {
      setFormError(ERRORS.INVALID_FORM)
      return
    }

    // When we are editing we have fields to progress through, if we are currently on one of them when submitting
    // that means the user has not hit save for them yet.
    const maxFieldIndex = canEditImage ? 1 : 0
    if (currentFieldIndex >= 0 && currentFieldIndex <= maxFieldIndex) {
      setFormError(ERRORS.UNSAVED_CHANGES)
      return
    }

    const form: RunnerEditForm = {
      name: selectedRunnerName,
      runnerGroupId: selectedRunnerGroupId,
      maximumConcurrentJobs: maxConcurrentJobs,
      isPublicIpEnabled,
      machineSpecId: selectedMachineSpec?.id || null,
      // Include image fields when editing is allowed (always for curated, FF-gated for partner/marketplace)
      // For custom image runners with standalone version selector, still send version even when canEditImage=false
      imageVersion: canEditImage || runnerHasCustomImage ? selectedImageVersion?.version || null : null,
      imageId: canEditImage ? selectedImage?.id || null : null,
      imageSource: canEditImage ? selectedImage?.source || null : null,
      // Include image generation toggle state - only when the toggle feature flag is enabled
      isImageGenerationEnabled: isImageGenerationToggleEnabled ? isImageGenerationEnabled : null,
    }

    try {
      const success = await updateRunner(form, runnerId, entityLogin, isEnterprise)
      if (success) {
        navigate(runnerDetailsPath({isEnterprise, entityLogin, runnerId}))
      } else {
        setFormError(ERRORS.UPDATE_FAILED_REASON_UNKNOWN)
      }
    } catch (error: unknown) {
      setFormError((error as Error)?.message ?? ERRORS.UPDATE_FAILED_REASON_UNKNOWN)
    }
  }

  const onCancel = () => {
    navigate(runnerDetailsPath({isEnterprise, entityLogin, runnerId}))
  }

  return (
    <DocsContext value={docsUrlBase}>
      {formError && <Flash variant="danger">{formError}</Flash>}
      <PageLayout padding="none">
        <PageLayout.Header style={{marginBottom: '16px !important'}}>
          <Heading as="h2" className="h2 text-normal">
            <Link href={runnerListPath} data-testid="subhead-runner-list-path">
              Runners
            </Link>
            &nbsp;/ Edit {runnerName}
          </Heading>
          <Box sx={{borderBottom: '1px solid', borderColor: 'border.default', pt: '8px'}} />
        </PageLayout.Header>
        <PageLayout.Content>
          {/* noValidate disables native browser validation, that causes inaccessible tooltip to appear */}
          <form onSubmit={handleSubmit} noValidate data-hpc>
            <Box sx={{display: 'flex', flexDirection: 'column', gap: 4}}>
              <div data-testid="runner-name-input-section">
                <RunnerNameInput
                  runnerName={selectedRunnerName}
                  onChange={setSelectedRunnerName}
                  validationError={runnerNameError}
                  onValidationError={setRunnerNameError}
                />
              </div>
              <Box
                sx={{display: 'flex', flexDirection: 'column', gap: 2}}
                data-testid="edit-runner-specifications-section"
              >
                <Heading as="h3" className="h3 text-normal">
                  Runner specifications
                </Heading>
                {!canEditImage && runnerHasCustomImage && (
                  <ImageVersionSelector
                    imageVersions={imageVersions}
                    selectedImageVersion={selectedImageVersion}
                    setSelectedImageVersion={setSelectedImageVersion}
                  />
                )}
              </Box>
              <Box sx={{display: 'flex', flexDirection: 'column'}}>
                <FieldProgression
                  fields={[
                    // Image editing: always available for curated, FF-gated for partner/marketplace
                    ...(canEditImage
                      ? [
                          {
                            name: 'Image',
                            displayValue: selectedImageDisplayName,
                            error: imageError,
                            editComponent: (
                              <ImageSelector
                                allImages={images}
                                platform={runnerPlatform}
                                value={selectedImage}
                                setValue={setSelectedImage}
                                onValidationError={setImageError}
                                isImageGenerationEnabled={isImageGenerationEnabled}
                                setIsImageGenerationEnabled={setIsImageGenerationEnabled}
                                imageVersion={selectedImageVersion}
                                setImageVersion={setSelectedImageVersion}
                                isImageGenerationFeatureEnabled={isImageGenerationToggleEnabled}
                                isCustomImagesPolicyEnabled={isCustomImagesPolicyEnabled}
                                hidePartnerAndCustomTabs={hidePartnerAndCustomTabs}
                              />
                            ),
                          },
                        ]
                      : []),
                    {
                      name: 'Size',
                      displayValue: selectedMachineSpec
                        ? machineSpecDisplayText(selectedMachineSpec).closedBoxSummary
                        : null,
                      error: machineSpecError,
                      editComponent: (
                        <MachineSpecSelect
                          value={selectedMachineSpec}
                          setValue={setSelectedMachineSpec}
                          onSelect={() => setMachineSpecError(false)}
                          runnerImage={selectedImage}
                          platform={runnerPlatform}
                          options={machineSpecs}
                          isImageGenerationEnabled={isImageGenerationEnabled}
                          runnerImageVersion={selectedImageVersion}
                        />
                      ),
                    },
                  ]}
                  skipResetFieldOnSave
                  key={fieldProgressionKey}
                  currentFieldIndex={currentFieldIndex}
                  setCurrentFieldIndex={setCurrentFieldIndex}
                />
              </Box>
              <Box sx={{display: 'flex', flexDirection: 'column', gap: 2}}>
                <Heading as="h3" className="h3 text-normal">
                  Capacity
                </Heading>
                <RunnerMaxConcurrencyInput
                  value={maxConcurrentJobs}
                  min={maxConcurrentJobsMin}
                  max={maxConcurrentJobsMax}
                  gpuRunnerSelected={runnerHasGpuSpec}
                  onChange={setMaxConcurrentJobs}
                />
              </Box>
              <Box sx={{display: 'flex', flexDirection: 'column', gap: 2}} data-testid="runner-group-section">
                <Heading as="h3" className="h3 text-normal">
                  Permissions
                </Heading>
                {selectedRunnerGroup?.allowPublic && isImageGenerationEnabled && (
                  <InlineMessage variant="critical">
                    It is not safe to use Larger runners with custom image generation enabled in public repositories.
                    Public repositories can potentially inject dangerous packages or malware into your images that can
                    then be used in your CI workflows.
                  </InlineMessage>
                )}
                <RunnerGroupSelector
                  value={selectedRunnerGroupId}
                  setValue={setSelectedRunnerGroupId}
                  groups={runnerGroups}
                  validationError={runnerGroupError}
                />
              </Box>
              <Box sx={{display: 'flex', flexDirection: 'column', gap: 2}}>
                <Heading as="h3" className="h3 text-normal">
                  Networking
                </Heading>
                <RunnerPublicIpCheckbox
                  checked={isPublicIpEnabled}
                  onChange={setIsPublicIpEnabled}
                  isPublicIpAllowed={isPublicIpAllowed}
                  runnerHasPublicIp={runnerHasPublicIp}
                  publicIpInfoPath={publicIpInfoPath}
                />
              </Box>
            </Box>
            <Box sx={{display: 'flex', flexDirection: 'row', gap: 3, mt: 3}}>
              <Button type="submit" variant="primary" data-testid="edit-runner-save-button">
                Save
              </Button>
              <Button type="button" variant="default" data-testid="edit-runner-cancel-button" onClick={onCancel}>
                Cancel
              </Button>
            </Box>
          </form>
        </PageLayout.Content>
      </PageLayout>
    </DocsContext>
  )
}
